(() => {
  const els = [...document.querySelectorAll('*')].filter(e => e.children.length===0 && /Scrum Better with Kanban/i.test(e.textContent));
  return els.map(e => {
    const r = e.getBoundingClientRect();
    return {tag:e.tagName, cls:e.className, x:Math.round(r.x+r.width/2), y:Math.round(r.y+r.height/2), vis:r.width>0&&r.height>0};
  });
})();

(() => {
  const spans = [...document.querySelectorAll('span.wCourseSearch__CertOption__Name')];
  const target = spans.find(s => /Scrum Better with Kanban/i.test(s.textContent));
  if(!target) return 'not found';
  const clickable = target.closest('button, a, [role="button"], li, div');
  target.scrollIntoView({block:'center'});
  (clickable||target).click();
  return 'clicked: '+(clickable?clickable.tagName+'.'+clickable.className:target.tagName);
})();

(() => {
  const cards = [...document.querySelectorAll('[class*="wCourseSearch__Result"], [class*="CourseCard"], article')];
  // Fallback: parse by trainer links + company
  const trainers = [...document.querySelectorAll('a[href*="/trainer-search/trainer/"]')].map(a=>a.textContent.trim());
  // Grab the results summary
  const summary = document.body.innerText.match(/\d+ courses found/);
  const addl = document.body.innerText.match(/\d+ additional courses/);
  return {summary: summary&&summary[0], additional: addl&&addl[0], trainers: [...new Set(trainers)]};
})();

(() => {
  const links = [...document.querySelectorAll('a[href*="/courses/"]')];
  // find those near Erkan Kadir / Superheroes
  const out = [];
  document.querySelectorAll('a[href*="/courses/"], button').forEach(el=>{
    if(/more details/i.test(el.textContent) && el.getAttribute('href')) out.push(el.getAttribute('href'));
  });
  // Also map course detail links generally
  const detail = links.map(a=>a.getAttribute('href')).filter(h=>/\/courses\/\d+/.test(h));
  return {moreDetails: out, detailLinks:[...new Set(detail)]};
})();
